#!/usr/bin/env python3
"""
PortKit Reward Functions for Tinker GRPO Training
===================================================
Custom reward functions for evaluating Minecraft Java→Bedrock mod conversion quality.

These reward functions are used during GRPO training to score model completions
against ground truth Bedrock add-on outputs.
"""

import json
import re
from typing import Optional


def extract_manifest(text: str) -> Optional[str]:
    """Extract manifest.json content from model output."""
    json_blocks = re.findall(r"```json\s*(.*?)\s*```", text, re.DOTALL)
    for block in json_blocks:
        if "format_version" in block or "header" in block:
            return block.strip()
    section = re.search(r"## Bedrock Add-on Output(.*?)(?:##|$)", text, re.DOTALL)
    if section:
        m = re.search(r'\{[^{}]*"format_version"[^{}]*\}', section.group(1), re.DOTALL)
        if m:
            return m.group(0)
    return None


def extract_js(text: str) -> Optional[str]:
    """Extract JavaScript content from model output."""
    js_blocks = re.findall(r"```(?:javascript|js)\s*(.*?)\s*```", text, re.DOTALL)
    if js_blocks:
        return max(js_blocks, key=len).strip()
    return None


def extract_json_blocks(text: str) -> list[str]:
    """Extract all JSON code blocks from text."""
    return re.findall(r"```json\s*(\{[^}]*(?:\{[^}]*\}[^}]*)*\})", text, re.DOTALL)


def extract_js_blocks(text: str) -> list[str]:
    """Extract all JS code blocks from text."""
    return re.findall(r"```(?:javascript|js)\s*([\s\S]*?)```", text)


def extract_all_sections(text: str) -> dict[str, list[str]]:
    """Extract structured sections (manifest, JS) from completion."""
