#!/usr/bin/env python3
"""
Convert MMSD validated_pairs.jsonl to Tinker conversations.jsonl format.

Input (MMSD):
  {instruction, reasoning_trace, java_source, bedrock_source}

Output (Tinker conversations.jsonl):
  {"messages": [{system}, {user}, {assistant}]}

Also supports adding general Java/JS code data (12% mix) for
catastrophic forgetting mitigation.
"""

import json
import argparse
import random
from pathlib import Path

SYSTEM_PROMPT = (
    "You are PortKit, an expert at converting Minecraft Java Edition mods (Forge) "
    "to Bedrock Edition Add-ons. Given a mod description and Java source code, "
    "first reason through the platform mapping, then produce the Bedrock Add-on implementation."
)


def convert_pair(row: dict) -> dict:
    """Convert a single MMSD pair to Tinker conversation format."""
    user_content = (
        f"Mod Description: {row['instruction']}\n\n"
        f"Java Source:\n{row['java_source']}\n\n"
        "Convert this to a Bedrock Add-on. First explain your conversion approach, "
        "then provide the files."
    )
    assistant_content = (
        f"## Conversion Plan\n{row['reasoning_trace']}\n\n"
        f"## Bedrock Add-on Output\n{row['bedrock_source']}"
    )
    return {
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": user_content},
            {"role": "assistant", "content": assistant_content},
        ]
    }


def convert_pair_no_reasoning(row: dict) -> dict:
    """Stage B format: direct conversion without reasoning trace."""
    user_content = (
        f"Mod Description: {row['instruction']}\n\n"
        f"Java Source:\n{row['java_source']}\n\n"
        "Convert this to a Bedrock Add-on."
    )
    return {
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": user_content},
            {"role": "assistant", "content": row["bedrock_source"]},
        ]
    }


def load_general_code_sample(sample_size: int = 200, seed: int = 42) -> list[dict]:
    """Load general Java/JS code data for forgetting mitigation (12% mix).

    Uses m-a-p/CodeFeedback-Filtered-Instruction from HuggingFace.
    Falls back to empty list if dataset not available.
    """
    try:
        from datasets import load_dataset

        print("Loading general code dataset (m-a-p/CodeFeedback-Filtered-Instruction)...")
        ds = load_dataset(
            "m-a-p/CodeFeedback-Filtered-Instruction", split="train", streaming=True
        )

        java_js_samples = []
        for row in ds:
            lang = row.get("lang", "")
            if lang in ("java", "javascript"):
                java_js_samples.append(row)
                if len(java_js_samples) >= sample_size * 3:
                    break

        random.seed(seed)
        random.shuffle(java_js_samples)
        selected = java_js_samples[:sample_size]

        conversations = []
        for row in selected:
            conversations.append({
                "messages": [
                    {"role": "user", "content": row["query"]},
                    {"role": "assistant", "content": row["answer"]},
                ]
            })
        print(f"  Loaded {len(conversations)} general code samples")
        return conversations

